// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Get OIDC signing keys
	// (GET /.well-known/jwks.json)
	GetOpenIdJwks(c *gin.Context)
	// Get OIDC discovery metadata
	// (GET /.well-known/openid-configuration)
	GetOpenIdConfiguration(c *gin.Context)
	// Send a magic-link email to bind an address to the current user
	// (POST /auth/email/bind/request)
	RequestEmailBind(c *gin.Context)
	// Create a fresh Bot-scoped TAT transport
	// (POST /auth/federation/bots/{bot_id}/tat/session)
	CreateFederationTatSession(c *gin.Context, botId string, params CreateFederationTatSessionParams)
	// Validate a federation authorization request
	// (GET /auth/federation/context)
	GetFederationContext(c *gin.Context, params GetFederationContextParams)
	// Exchange a handoff ticket for an opaque delegated session
	// (POST /auth/federation/exchange)
	ExchangeFederationTicket(c *gin.Context, params ExchangeFederationTicketParams)
	// Issue a short-lived federation handoff ticket
	// (POST /auth/federation/tickets)
	IssueFederationTicket(c *gin.Context)
	// Activate the current authenticated user with an invite code
	// (POST /auth/invite/activate)
	ActivateInviteCode(c *gin.Context)
	// Validate an invite code
	// (POST /auth/invite/validate)
	ValidateInviteCode(c *gin.Context)
	// Trigger forgot-password flow placeholder
	// (POST /auth/password/forgot)
	ForgotPassword(c *gin.Context)
	// Sign in with email and password
	// (POST /auth/password/sign-in)
	SignInWithPassword(c *gin.Context)
	// Register with email and password
	// (POST /auth/password/sign-up)
	SignUpWithPassword(c *gin.Context)
	// List the current user's signed payment cards
	// (GET /auth/payment-methods)
	ListPaymentMethods(c *gin.Context, params ListPaymentMethodsParams)
	// Create a hosted card signing order for the current user
	// (POST /auth/payment-methods/sign-orders)
	CreatePaymentMethodSignOrder(c *gin.Context)
	// Delete one of the current user's non-default signed cards
	// (DELETE /auth/payment-methods/{contractCode})
	DeletePaymentMethod(c *gin.Context, contractCode PaymentMethodContractCode)
	// Set one of the current user's signed cards as default
	// (PUT /auth/payment-methods/{contractCode}/default)
	SetDefaultPaymentMethod(c *gin.Context, contractCode PaymentMethodContractCode)
	// Get the current user profile
	// (GET /auth/profile)
	GetProfile(c *gin.Context)
	// Update the current user profile
	// (PUT /auth/profile)
	UpdateProfile(c *gin.Context)
	// Redirect to the current user's avatar asset
	// (GET /auth/profile/avatar)
	GetProfileAvatar(c *gin.Context)
	// Upload and replace the current user's avatar
	// (PUT /auth/profile/avatar)
	UpdateProfileAvatar(c *gin.Context)
	// Start a FaceID real-name verification attempt
	// (POST /auth/realname/faceid/attempts)
	StartRealnameFaceIDAttempt(c *gin.Context)
	// Read the current recoverable FaceID attempt for the authenticated user
	// (GET /auth/realname/faceid/attempts/current)
	GetCurrentRealnameFaceIDAttempt(c *gin.Context)
	// Reconcile and read an owned FaceID attempt
	// (GET /auth/realname/faceid/attempts/{attemptId})
	GetRealnameFaceIDAttempt(c *gin.Context, attemptId string)
	// Synchronize an attempt to Shadow and activate final verification
	// (POST /auth/realname/faceid/attempts/{attemptId}/finalize)
	FinalizeRealnameFaceIDAttempt(c *gin.Context, attemptId string)
	// Send a Shadow verification code to the current phone for a FaceID attempt
	// (POST /auth/realname/faceid/attempts/{attemptId}/send-phone-code)
	SendRealnameFaceIDPhoneCode(c *gin.Context, attemptId string)
	// Verify the current phone through Shadow binding for a FaceID attempt
	// (POST /auth/realname/faceid/attempts/{attemptId}/verify-phone)
	VerifyRealnameFaceIDPhone(c *gin.Context, attemptId string)
	// Receive a Tencent FaceID browser redirect
	// (GET /auth/realname/faceid/callback)
	HandleRealnameFaceIDCallback(c *gin.Context, params HandleRealnameFaceIDCallbackParams)
	// Retry syncing current user's verified real-name identity to the account system
	// (POST /auth/realname/sync/retry)
	RetryRealnameSync(c *gin.Context)
	// Verify current user's real-name identity
	// (POST /auth/realname/verify)
	VerifyRealname(c *gin.Context)
	// Verify current user's phone as the third real-name factor
	// (POST /auth/realname/verify-phone)
	VerifyRealnamePhone(c *gin.Context)
	// Delete the current session
	// (DELETE /auth/session)
	SignOut(c *gin.Context)
	// Get the current session
	// (GET /auth/session)
	GetCurrentSession(c *gin.Context)
	// Get current user's Lightvela shadow binding status
	// (GET /auth/shadow/binding)
	GetShadowBinding(c *gin.Context)
	// Retry current user's failed Lightvela shadow binding
	// (POST /auth/shadow/binding/retry)
	RetryShadowBinding(c *gin.Context)
	// Send an SMS verification code
	// (POST /auth/sms/send)
	SendSmsCode(c *gin.Context)
	// Verify SMS code and create a session
	// (POST /auth/sms/verify)
	VerifySmsCode(c *gin.Context)
	// Create a one-time Tencent Cloud console login redirect for the current user
	// (POST /auth/tencent-cloud/redirect)
	CreateTencentCloudRedirect(c *gin.Context)
	// Validate OIDC request and redirect to the authorization page
	// (GET /oauth2/authorize)
	GetOidcAuthorize(c *gin.Context, params GetOidcAuthorizeParams)
	// Confirm an OIDC authorization request and issue a code
	// (POST /oauth2/authorize)
	AuthorizeOidc(c *gin.Context)
	// Validate an OIDC authorization request and return session context
	// (GET /oauth2/authorize/context)
	GetOidcAuthorizeContext(c *gin.Context, params GetOidcAuthorizeContextParams)
	// Exchange an OIDC authorization code for tokens
	// (POST /oauth2/token)
	ExchangeOidcToken(c *gin.Context)
}

