func (siw *ServerInterfaceWrapper) ExchangeOidcToken(c *gin.Context) {

	for _, middleware := range siw.HandlerMiddlewares {
		middleware(c)
		if c.IsAborted() {
			return
		}
	}

	siw.Handler.ExchangeOidcToken(c)
}

// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/.well-known/jwks.json", wrapper.GetOpenIdJwks)
	router.GET(options.BaseURL+"/.well-known/openid-configuration", wrapper.GetOpenIdConfiguration)
	router.POST(options.BaseURL+"/auth/email/bind/request", wrapper.RequestEmailBind)
	router.POST(options.BaseURL+"/auth/federation/bots/:bot_id/tat/session", wrapper.CreateFederationTatSession)
	router.GET(options.BaseURL+"/auth/federation/context", wrapper.GetFederationContext)
	router.POST(options.BaseURL+"/auth/federation/exchange", wrapper.ExchangeFederationTicket)
	router.POST(options.BaseURL+"/auth/federation/tickets", wrapper.IssueFederationTicket)
	router.POST(options.BaseURL+"/auth/invite/activate", wrapper.ActivateInviteCode)
	router.POST(options.BaseURL+"/auth/invite/validate", wrapper.ValidateInviteCode)
	router.POST(options.BaseURL+"/auth/password/forgot", wrapper.ForgotPassword)
	router.POST(options.BaseURL+"/auth/password/sign-in", wrapper.SignInWithPassword)
	router.POST(options.BaseURL+"/auth/password/sign-up", wrapper.SignUpWithPassword)
	router.GET(options.BaseURL+"/auth/payment-methods", wrapper.ListPaymentMethods)
	router.POST(options.BaseURL+"/auth/payment-methods/sign-orders", wrapper.CreatePaymentMethodSignOrder)
	router.DELETE(options.BaseURL+"/auth/payment-methods/:contractCode", wrapper.DeletePaymentMethod)
	router.PUT(options.BaseURL+"/auth/payment-methods/:contractCode/default", wrapper.SetDefaultPaymentMethod)
	router.GET(options.BaseURL+"/auth/profile", wrapper.GetProfile)
	router.PUT(options.BaseURL+"/auth/profile", wrapper.UpdateProfile)
	router.GET(options.BaseURL+"/auth/profile/avatar", wrapper.GetProfileAvatar)
	router.PUT(options.BaseURL+"/auth/profile/avatar", wrapper.UpdateProfileAvatar)
	router.POST(options.BaseURL+"/auth/realname/faceid/attempts", wrapper.StartRealnameFaceIDAttempt)
	router.GET(options.BaseURL+"/auth/realname/faceid/attempts/current", wrapper.GetCurrentRealnameFaceIDAttempt)
	router.GET(options.BaseURL+"/auth/realname/faceid/attempts/:attemptId", wrapper.GetRealnameFaceIDAttempt)
	router.POST(options.BaseURL+"/auth/realname/faceid/attempts/:attemptId/finalize", wrapper.FinalizeRealnameFaceIDAttempt)
	router.POST(options.BaseURL+"/auth/realname/faceid/attempts/:attemptId/send-phone-code", wrapper.SendRealnameFaceIDPhoneCode)
	router.POST(options.BaseURL+"/auth/realname/faceid/attempts/:attemptId/verify-phone", wrapper.VerifyRealnameFaceIDPhone)
	router.GET(options.BaseURL+"/auth/realname/faceid/callback", wrapper.HandleRealnameFaceIDCallback)
	router.POST(options.BaseURL+"/auth/realname/sync/retry", wrapper.RetryRealnameSync)
	router.POST(options.BaseURL+"/auth/realname/verify", wrapper.VerifyRealname)
	router.POST(options.BaseURL+"/auth/realname/verify-phone", wrapper.VerifyRealnamePhone)
	router.DELETE(options.BaseURL+"/auth/session", wrapper.SignOut)
	router.GET(options.BaseURL+"/auth/session", wrapper.GetCurrentSession)
	router.GET(options.BaseURL+"/auth/shadow/binding", wrapper.GetShadowBinding)
	router.POST(options.BaseURL+"/auth/shadow/binding/retry", wrapper.RetryShadowBinding)
	router.POST(options.BaseURL+"/auth/sms/send", wrapper.SendSmsCode)
	router.POST(options.BaseURL+"/auth/sms/verify", wrapper.VerifySmsCode)
	router.POST(options.BaseURL+"/auth/tencent-cloud/redirect", wrapper.CreateTencentCloudRedirect)
	router.GET(options.BaseURL+"/oauth2/authorize", wrapper.GetOidcAuthorize)
	router.POST(options.BaseURL+"/oauth2/authorize", wrapper.AuthorizeOidc)
	router.GET(options.BaseURL+"/oauth2/authorize/context", wrapper.GetOidcAuthorizeContext)
	router.POST(options.BaseURL+"/oauth2/token", wrapper.ExchangeOidcToken)
}

